import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor name uniqueness", () => {
  test("rejects a vendor name that matches an existing one in the tenant, ignoring case", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange: a unique suffix keeps this test isolated from other parallel tests sharing the database.
    const member = await apiAs("member");
    const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
    const existingName = `Acme Freight ${suffix}`;
    const duplicateName = `acme freight ${suffix}`;

    const existing = await member.post("/api/vendors", {
      data: { name: existingName, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    await expectStatus(existing, 201);

    // Act
    const response = await member.post("/api/vendors", {
      data: { name: duplicateName, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");
  });
});
